class Bag:
    def __init__(self, items):
        self.items = list(items)

    def __len__(self):
        return len(self.items)

    def __getitem__(self, index):
        return self.items[index]

    def __str__(self):
        return "Bag" + str(self.items)

b = Bag(["sword", "shield"])
print(b)
print(len(b))
print(b[1])

class Player:
    def __init__(self, name):
        self.name = name

    def describe(self):
        return f"player {self.name}"

class Boss(Player):
    def __init__(self, name, hitpoints):
        super().__init__(name)
        self.hitpoints = hitpoints

    def describe(self):
        return super().describe() + f" with {self.hitpoints} hp"

b = Boss("Gnu", 500)
print(b.describe())
print(isinstance(b, Player))

