#native <Embed>
#native <Stdio>

int main() {
    /* seed two slots the Python side will read */
    Embed.SendValue(type="python", name="target", 400.0);
    Embed.SendValue(type="python", name="speed", 3.0);

    Embed.Run(type="python");       /* runs scripts/main.py */
    Embed.Stop(type="python");      /* waits for the window to close */

    /* read back what Python wrote */
    int score = Embed.GetValue(type="python", name="score");
    Stdio.printf("score = {}\n", score);
    return 0;
}

